-- Row counts after load
SELECT table_name, table_rows_exact FROM (
  SELECT 'regions' AS table_name, COUNT(*) AS table_rows_exact FROM regions
  UNION ALL
  SELECT 'branches' AS table_name, COUNT(*) AS table_rows_exact FROM branches
  UNION ALL
  SELECT 'products' AS table_name, COUNT(*) AS table_rows_exact FROM products
  UNION ALL
  SELECT 'officers' AS table_name, COUNT(*) AS table_rows_exact FROM officers
  UNION ALL
  SELECT 'customers' AS table_name, COUNT(*) AS table_rows_exact FROM customers
  UNION ALL
  SELECT 'customer_contacts' AS table_name, COUNT(*) AS table_rows_exact FROM customer_contacts
  UNION ALL
  SELECT 'legacy_id_map' AS table_name, COUNT(*) AS table_rows_exact FROM legacy_id_map
  UNION ALL
  SELECT 'loan_accounts' AS table_name, COUNT(*) AS table_rows_exact FROM loan_accounts
  UNION ALL
  SELECT 'disbursements' AS table_name, COUNT(*) AS table_rows_exact FROM disbursements
  UNION ALL
  SELECT 'collateral' AS table_name, COUNT(*) AS table_rows_exact FROM collateral
  UNION ALL
  SELECT 'emi_schedule' AS table_name, COUNT(*) AS table_rows_exact FROM emi_schedule
  UNION ALL
  SELECT 'repayments' AS table_name, COUNT(*) AS table_rows_exact FROM repayments
  UNION ALL
  SELECT 'nach_mandates' AS table_name, COUNT(*) AS table_rows_exact FROM nach_mandates
  UNION ALL
  SELECT 'finance_npa_oct2026' AS table_name, COUNT(*) AS table_rows_exact FROM finance_npa_oct2026
  UNION ALL
  SELECT 'risk_npa_oct2026' AS table_name, COUNT(*) AS table_rows_exact FROM risk_npa_oct2026
  UNION ALL
  SELECT 'cbs_extract_oct2026' AS table_name, COUNT(*) AS table_rows_exact FROM cbs_extract_oct2026
  UNION ALL
  SELECT 'dw_snapshot_oct2026' AS table_name, COUNT(*) AS table_rows_exact FROM dw_snapshot_oct2026
  UNION ALL
  SELECT 'load_manifest' AS table_name, COUNT(*) AS table_rows_exact FROM load_manifest
) c;
